style.css:
@-moz-document domain("thuisbezorgd.nl") {
html, body {
        background: #282a36 !important;
        color: #f8f8f2 !important;
    }
    header, nav, footer, .main-header, .footer, .navbar, .header, .content, .main-content, .container, .app__header, .app__footer {
        background: #21222c !important;
        color: #f8f8f2 !important;
    }
    a, .link, button, .btn {
        color: #ffb86c !important;
        background: transparent !important;
        border-color: #bd93f9 !important;
    }
    input, textarea, select, .form-control {
        background: #44475a !important;
        color: #f8f8f2 !important;
        border-color: #6272a4 !important;
    }
    .card, .panel, .box, .order, .restaurant, .restaurant-card, .popup, .modal, .dropdown-menu {
        background: #343746 !important;
        color: #f8f8f2 !important;
        border-radius: 10px !important;
        border-color: #6272a4 !important;
    }
    ::-webkit-scrollbar {
        background: #282a36 !important;
    }
    ::-webkit-scrollbar-thumb {
        background: #44475a !important;
    }
    * {
        border-color: #44475a !important;
    }
    img, svg, .icon {
        filter: brightness(0.85) !important;
    }
    /* Focus state */
    *:focus {
        outline: 1px solid #ff79c6 !important;
    }
    /* Notification, error, success colors */
    .alert, .error, .notification, .toast {
        background: #ff5555 !important;
        color: #f8f8f2 !important;
    }
    .success, .alert-success {
        background: #50fa7b !important;
        color: #282a36 !important;
    }
    /* Button hover/active */
    button:hover, .btn:hover, a:hover {
        background: #6272a4 !important;
        color: #f8f8f2 !important;
    }
}
